from pathlib import Path
import subprocess,json,hashlib,sys
root=Path(__file__).resolve().parents[3]
paths={str(p.relative_to(root)) for p in (root/'internal/oracle/testdata/review').rglob('*.a')}
for line in (root/'cloud/fast-gate/smoke.txt').read_text().splitlines():
 fields=line.split()
 if fields and not fields[0].startswith('#'): paths.add(fields[-1])
hashes={};accepted=0
for path in sorted(paths):
 run=subprocess.run([sys.argv[1],'c',str(root/path)],capture_output=True,timeout=60,cwd=root)
 if run.returncode==0:
  assert b'Generated by adamic' in run.stdout,path
  hashes[path]=hashlib.sha256(run.stdout).hexdigest();accepted+=1
 else: hashes[path]='refused'
(root/'internal/native/testdata/source-lines-release.json').write_text(json.dumps(hashes,indent=2)+'\n')
print(f'{len(hashes)} review/smoke entries: {accepted} emitted C hashes; {len(hashes)-accepted} refused')
(root/'internal/native/testdata/source-lines-release.sha').write_text(sys.argv[2]+'\n')
